style.css:
/* GHOST:// TERMINAL — Global */
 /* i really want this to be global */

:root {
    /* swap these colors if you want */
    --my-bg: #080c08;
    --my-panel: #0d140d;
    --my-green: #39ff75;
    --my-dim: #168c43;
    --my-text: #c4f5ce;
    --my-border: #174d2b;
}

/* terminal backgrounds */
html, body {
    background-color: var(--my-bg) !important;
    color: var(--my-text) !important;
    font-family: "Consolas", "Courier New", monospace !important;
}

/* headings */
h1, h2, h3, h4, h5, h6 {
    color: var(--my-green) !important;
    font-family: "Consolas", monospace !important;
    text-shadow: 0 0 8px #39ff7544 !important;
}

/* links */
a {
    color: var(--my-green) !important;
}

/* form fields */
input, textarea, select {
    background: var(--my-panel) !important;
    color: var(--my-green) !important;
    border: 1px solid var(--my-border) !important;
    font-family: monospace !important;
}

/* buttons */
button {
    background: var(--my-panel) !important;
    color: var(--my-green) !important;
    border: 1px solid var(--my-dim) !important;
    border-radius: 2px !important;
    font-family: monospace !important;
    transition: 0.2s ease !important;
}

button:hover {
    background: #102b18 !important;
    box-shadow: 0 0 12px #39ff7544 !important;
}

/* images */
img {
    border-radius: 2px !important;
}

/* selection */
::selection {
    background: var(--my-green) !important;
    color: #000 !important;
}
